/** Registers the demo_config scalars with the master agent. */
void
init_demo_config(void)
{
    DEBUGMSGTL(("demo_config", "Initializing\n"));

    {
        static const oid deviceName_oid[] = { 1,3,6,1,4,1,99999,1,1 };

        netsnmp_register_scalar(
            netsnmp_create_handler_registration(
                "deviceName", handle_deviceName, deviceName_oid, OID_LENGTH(deviceName_oid),
                HANDLER_CAN_RWRITE));
    }
    {
        static const oid tempThresholdMilliC_oid[] = { 1,3,6,1,4,1,99999,1,2 };

        netsnmp_register_scalar(
            netsnmp_create_handler_registration(
                "tempThresholdMilliC", handle_tempThresholdMilliC, tempThresholdMilliC_oid, OID_LENGTH(tempThresholdMilliC_oid),
                HANDLER_CAN_RWRITE));
    }
    {
        static const oid adminStatusExt_oid[] = { 1,3,6,1,4,1,99999,1,3 };

        netsnmp_register_scalar(
            netsnmp_create_handler_registration(
                "adminStatusExt", handle_adminStatusExt, adminStatusExt_oid, OID_LENGTH(adminStatusExt_oid),
                HANDLER_CAN_RWRITE));
    }
    {
        static const oid sampleIntervalSec_oid[] = { 1,3,6,1,4,1,99999,1,4 };

        netsnmp_register_scalar(
            netsnmp_create_handler_registration(
                "sampleIntervalSec", handle_sampleIntervalSec, sampleIntervalSec_oid, OID_LENGTH(sampleIntervalSec_oid),
                HANDLER_CAN_RWRITE));
    }
}

