static int
handle_deviceName(netsnmp_mib_handler *handler,
          netsnmp_handler_registration *reginfo,
          netsnmp_agent_request_info *reqinfo,
          netsnmp_request_info *requests)
{
    (void)handler;
    (void)reginfo;
    storage_env_t *env;

#if STORAGE_MODE_deviceName == STORAGE_MODE_PERSISTENT
    env = config_env;
#else
    env = cache_env;
#endif

    switch (reqinfo->mode) {

    case MODE_GET:
        {
            unsigned char buf[64];
            size_t len = sizeof(buf);
            storage_rc_t rc = storage_get_bytes(env, "deviceName", buf, &len);

            if (rc == STORAGE_ERR_NOTFOUND) {
                netsnmp_set_request_error(reqinfo, requests, SNMP_NOSUCHINSTANCE);
                break;
            }
            if (rc != STORAGE_OK) {
                snmp_log(LOG_ERR, "deviceName: storage_get_bytes failed: %s\n",
                          storage_strerror(rc));
                netsnmp_set_request_error(reqinfo, requests, SNMP_ERR_GENERR);
                break;
            }
            snmp_set_var_typed_value(requests->requestvb, ASN_OCTET_STR, buf, len);
        }
        break;

    /*
     * SET REQUEST -- full net-snmp four phase state machine.
     * http://www.net-snmp.org/tutorial-5/toolkit/mib_module/set-actions.jpg
     */
    case MODE_SET_RESERVE1:
        {
            int ret = netsnmp_check_vb_type(requests->requestvb, ASN_OCTET_STR);

            if (ret != SNMP_ERR_NOERROR) {
                netsnmp_set_request_error(reqinfo, requests, SNMP_ERR_WRONGTYPE);
                break;
            }
            if (
                requests->requestvb->val_len > (size_t)(63)) {
                netsnmp_set_request_error(reqinfo, requests, SNMP_ERR_WRONGLENGTH);
                break;
            }
        }
        break;

    case MODE_SET_RESERVE2:
        {
            struct undo_deviceName { size_t len; unsigned char data[64]; };
            struct undo_deviceName *prev = malloc(sizeof(*prev));

            if (!prev) {
                netsnmp_set_request_error(reqinfo, requests, SNMP_ERR_RESOURCEUNAVAILABLE);
                break;
            }
            prev->len = sizeof(prev->data);
            {
                storage_rc_t rc = storage_get_bytes(env, "deviceName", prev->data, &prev->len);

                if (rc == STORAGE_ERR_NOTFOUND) {
                    prev->len = 0;
                } else if (rc != STORAGE_OK) {
                    free(prev);
                    netsnmp_set_request_error(reqinfo, requests, SNMP_ERR_RESOURCEUNAVAILABLE);
                    break;
                }
            }
            netsnmp_request_add_list_data(requests,
                netsnmp_create_data_list("undo_deviceName", prev, free));
        }
        break;

    case MODE_SET_FREE:
        /* RESERVE1/RESERVE2 failed somewhere; release any stash taken. */
        netsnmp_request_remove_list_data(requests, "undo_deviceName");
        break;

    case MODE_SET_ACTION:
        {
            storage_rc_t rc = storage_set_bytes(env, "deviceName",
                                                 requests->requestvb->val.string,
                                                 requests->requestvb->val_len);

            if (rc != STORAGE_OK) {
                snmp_log(LOG_ERR, "deviceName: storage_set_bytes failed: %s\n",
                          storage_strerror(rc));
                netsnmp_set_request_error(reqinfo, requests, SNMP_ERR_COMMITFAILED);
            }
        }
        break;

    case MODE_SET_COMMIT:
        /* Success: the stashed previous value is no longer needed. */
        netsnmp_request_remove_list_data(requests, "undo_deviceName");
        break;

    case MODE_SET_UNDO:
        {
            struct undo_deviceName { size_t len; unsigned char data[64]; };
            struct undo_deviceName *prev = netsnmp_request_get_list_data(requests, "undo_deviceName");

            if (prev) {
                storage_rc_t rc = storage_set_bytes(env, "deviceName", prev->data, prev->len);

                if (rc != STORAGE_OK) {
                    snmp_log(LOG_ERR, "deviceName: UNDO storage_set_bytes failed: %s\n",
                              storage_strerror(rc));
                    netsnmp_set_request_error(reqinfo, requests, SNMP_ERR_UNDOFAILED);
                }
            }
            netsnmp_request_remove_list_data(requests, "undo_deviceName");
        }
        break;

    default:
        snmp_log(LOG_ERR, "unknown mode (%d) in handle_deviceName\n", reqinfo->mode);
        return SNMP_ERR_GENERR;
    }

    return SNMP_ERR_NOERROR;
}

